function compress(chars) {
  const parts = [];
  let i = 0;
  while (i < chars.length) {
    let j = i;
    while (j < chars.length && chars[j] === chars[i]) j++;   // chars[i..j-1] is one run
    parts.push(chars[i]);
    if (j - i > 1) parts.push(String(j - i));
    i = j;
  }
  const result = parts.join("");              // O(n) extra memory
  for (let k = 0; k < result.length; k++) chars[k] = result[k];   // copy back into chars
  return result.length;
}

def compress(chars):
    parts = []
    i = 0
    while i < len(chars):
        j = i
        while j < len(chars) and chars[j] == chars[i]:
            j += 1                        # chars[i..j-1] is one run
        parts.append(chars[i])
        if j - i > 1:
            parts.append(str(j - i))
        i = j
    result = "".join(parts)               # O(n) extra memory
    chars[:len(result)] = list(result)    # copy back into chars
    return len(result)

int compress(char[] chars) {
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < chars.length) {
        int j = i;
        while (j < chars.length && chars[j] == chars[i]) j++;   // chars[i..j-1] is one run
        sb.append(chars[i]);
        if (j - i > 1) sb.append(j - i);
        i = j;
    }
    for (int k = 0; k < sb.length(); k++) chars[k] = sb.charAt(k);   // copy back into chars
    return sb.length();
}

